validator:
function validate(input) {
  const [{ MyNumbers = [] }] = input;
  for (const [num] of MyNumbers) {
    if (num === null) return 'Every row of MyNumbers needs a num.';
  }
  return null;
}

generator:
function generate(rand, size) {
  const MyNumbers = [];
  if (size === 'small') {
    // A tiny value pool makes repeats, triples and all-duplicate tables common.
    const pool = [-2, 0, 1, 3, 5, 6, 8];
    const rows = Math.floor(rand() * 9);
    for (let i = 0; i < rows; i++) MyNumbers.push([pool[Math.floor(rand() * pool.length)]]);
  } else {
    for (let i = 0; i < 2000; i++) MyNumbers.push([Math.floor(rand() * 1500) - 200]);
  }
  return [{ MyNumbers }];
}
